	private static CloseDisposition awaitCloseDisposition(Future<?> close, AtomicReference<Thread> closeThread,
			AtomicReference<Thread> advanceThread) {
		ThreadMXBean threadBean = ManagementFactory.getThreadMXBean();
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (System.nanoTime() < deadline) {
			if (close.isDone()) {
				return CloseDisposition.COMPLETED;
			}
			Thread closer = closeThread.get();
			Thread advancing = advanceThread.get();
			if (closer != null && advancing != null) {
				ThreadInfo info = threadBean.getThreadInfo(closer.getId());
				if (info != null && info.getThreadState() == Thread.State.BLOCKED
						&& info.getLockOwnerId() == advancing.getId()) {
					return CloseDisposition.BLOCKED_BY_ADVANCE;
				}
			}
			Thread.onSpinWait();
			Thread.yield();
		}
		return null;
	}

